-- READ ONLY. Authorization metadata and aggregate counts; no clinical/secret contents.
select jsonb_build_object(
 'history',(select jsonb_agg(version order by version) from supabase_migrations.schema_migrations),
 'executor',(select jsonb_build_object('login',rolcanlogin,'inherit',rolinherit,'superuser',rolsuper,'createrole',rolcreaterole,'createdb',rolcreatedb,'replication',rolreplication,'bypassrls',rolbypassrls) from pg_roles where rolname='rx_lifecycle_executor'),
 'memberships',(select coalesce(jsonb_agg(jsonb_build_object('role',roleid::regrole::text,'member',member::regrole::text,'admin',admin_option,'inherit',inherit_option,'set',set_option)),'[]'::jsonb) from pg_auth_members where roleid='rx_lifecycle_executor'::regrole or member='rx_lifecycle_executor'::regrole),
 'temporary_rights',jsonb_build_object('executor_public_create',has_schema_privilege('rx_lifecycle_executor','public','CREATE'),'executor_private_create',has_schema_privilege('rx_lifecycle_executor','rx_private','CREATE'),'executor_auth_usage',has_schema_privilege('rx_lifecycle_executor','auth','USAGE'),'postgres_set_executor',pg_has_role('postgres','rx_lifecycle_executor','SET'),'postgres_inherit_executor',pg_has_role('postgres','rx_lifecycle_executor','USAGE')),
 'public_rpcs',(select jsonb_agg(jsonb_build_object('name',p.proname,'owner',p.proowner::regrole::text,'definer',p.prosecdef,'config',p.proconfig,'public_execute',exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee=0 and a.privilege_type='EXECUTE'),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE')) order by p.proname) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('get_doctor_issue_review','issue_doctor_prescription','get_doctor_lifecycle','reveal_doctor_reference','cancel_doctor_prescription')),
 'private_helpers',(select jsonb_agg(jsonb_build_object('name',p.proname,'owner',p.proowner::regrole::text,'definer',p.prosecdef,'config',p.proconfig,'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE')) order by p.proname) from pg_proc p where p.pronamespace='rx_private'::regnamespace and p.proname in ('lifecycle_actor_id','assert_lifecycle_doctor','review_payload','new_reference','reference_digest','store_reference','recover_reference')),
 'app_role_isolation',(select jsonb_agg(jsonb_build_object('role',r,'set_executor',pg_has_role(r,'rx_lifecycle_executor','SET'),'inherit_executor',pg_has_role(r,'rx_lifecycle_executor','USAGE'),'digest_select',has_column_privilege(r,'public.prescriptions','reference_digest','SELECT'),'vault_usage',has_schema_privilege(r,'vault','USAGE'),'vault_decrypted_select',has_table_privilege(r,'vault.decrypted_secrets','SELECT'))) from unnest(array['anon','authenticated','service_role']) r),
 'rls',(select jsonb_agg(jsonb_build_object('name',schemaname||'.'||tablename,'enabled',rowsecurity) order by schemaname,tablename) from pg_tables where schemaname in ('public','rx_private')),
 'clinical_counts',jsonb_build_object('patients',(select count(*) from public.patients),'prescriptions',(select count(*) from public.prescriptions),'items',(select count(*) from public.prescription_items),'dispensations',(select count(*) from public.dispensations),'audit_events',(select count(*) from public.audit_events),'issuance_receipts',(select count(*) from rx_private.issuance_receipts),'cancellation_receipts',(select count(*) from rx_private.cancellation_receipts),'vault_records',(select count(*) from vault.secrets)),
 'active_clinical_calls',(select count(*) from pg_stat_activity where pid<>pg_backend_pid() and state='active' and query ~ '(save_doctor_draft|delete_doctor_draft|issue_doctor_prescription|cancel_doctor_prescription|reveal_doctor_reference)')
) as verification;
